(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+wx1, my = y+wy1;
  const wx2 = Math.sin(mx*0.025-t*0.4)*8+Math.cos(my*0.03+t*0.3)*6;
  const wy2 = Math.cos(mx*0.022+t*0.35)*8+Math.sin(my*0.028-t*0.45)*6;
  const sx = mx+wx2, sy = my+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.5],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,2.5],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*50,0.11,2.1,3],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75)*60,0.085,1.8,3.5]
  ];
  let act=0,inh=0,mod=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp+ph);
    inh+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    mod+=Math.sin(d*f*1.3-t*sp*0.8+ph*2)*0.5;
  }
  act/=8;inh/=8;mod/=8;
  let v=0,a=0.5,fx=sx,fy=sy;
  for(let i=0;i<4;i++){
    v+=a*(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1));
    fx=fx*1.8+v*0.5;fy=fy*1.8+v*0.3;a*=0.5;
  }
  const bg=v/2;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2-t*2)*0.5)/2.5;
  const du=act-inh*0.7+bg*0.2+spiral*0.3;
  const feed=0.035+bg*0.01,kill=0.06+spiral*0.015;
  const reaction=Math.tanh(du*2.2+(-du*kill+feed)*0.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+mod*0.3)*1.5)*0.3;
  const moire=Math.sin(sx*0.08)*Math.sin(sy*0.08)*Math.sin((sx-sy)*0.06+t*0.5)*0.4;
  const blend=reaction*0.55+cell*0.2+moire*0.15+mod*0.1;
  const val=blend*0.5+0.5;
  const pal=[[6,12,58],[12,45,95],[18,90,120],[30,150,140],[120,195,130],[210,200,80],[230,140,60],[200,70,60],[120,30,55],[60,15,50],[6,12,58]];
  const idx=val*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.1+(Math.abs(reaction)-0.65)*0.3:1.0;
  const hl=Math.max(0,mod)*0.15;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hl*60)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hl*40)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+hl*20)|0];
}
